function taskTitle(id:string){return store.workspace?.tasks.find(task=>task.id===id)?.title??id}
function revealDependency(dependency:Dependency){store.revealTask(dependency.from);store.revealTask(dependency.to);toast.value=`Relação ${dependency.type} revelada`;setTimeout(()=>toast.value='',3000)}
async function toggleProjectMenu(){projectMenu.value=!projectMenu.value;if(!projectMenu.value||projects.value.length)return;projectLoading.value=true;try{const response=await fetch('/api/v1/todoist/projects',{headers:{Accept:'application/json'}});if(!response.ok)throw new Error('Não foi possível carregar os projetos do Todoist.');projects.value=(await response.json()).data}catch(error){toast.value=error instanceof Error?error.message:'Não foi possível carregar projetos.';projectMenu.value=false;setTimeout(()=>toast.value='',3500)}finally{projectLoading.value=false}}
async function switchProject(project:{id:string;name:string}){try{const response=await fetch('/api/v1/todoist/project',{method:'POST',headers:{'Content-Type':'application/json',Accept:'application/json',...csrfHeaders()},body:JSON.stringify({todoist_project_id:project.id,commandId:crypto.randomUUID()})});if(!response.ok)throw new Error('Não foi possível trocar o projeto.');projectMenu.value=false;await store.load();toast.value=`Projeto ${project.name} selecionado`}catch(error){toast.value=error instanceof Error?error.message:'Não foi possível trocar o projeto.'}setTimeout(()=>toast.value='',3500)}
function simulationPayload(task:Task){if(!task.start)throw new Error('Defina uma data inicial antes de simular.');const intent={taskId:task.id,start:task.start,finish:task.finish};pendingIntent.value=intent;return {commandId:crypto.randomUUID(),intent}}
async function simulate(task=activeTask.value){if(!task){toast.value='Selecione ou mova uma tarefa para simular.';setTimeout(()=>toast.value='',3500);return false}simulating.value=true;simulation.value=null;try{const response=await fetch('/api/v1/schedule/simulate',{method:'POST',headers:{'Content-Type':'application/json',Accept:'application/json',...csrfHeaders()},body:JSON.stringify(simulationPayload(task))});if(!response.ok)throw new Error('Não foi possível calcular o cenário.');simulation.value=(await response.json()).data;if(store.workspace?.calendar?.rescheduling_mode==='AUTOMATIC'){toast.value='Aplicando cenário automaticamente';await applySimulation()}else toast.value=`Simulação pronta: ${simulation.value?.changes.length??0} tarefa(s) seriam ajustadas`;return true}catch(error){toast.value=error instanceof Error?error.message:'Não foi possível calcular o cenário.';return false}finally{simulating.value=false;setTimeout(()=>toast.value='',3500)}}
async function watchOperation(operationId:string){const response=await fetch(`/api/v1/schedule/operations/${operationId}`,{headers:{Accept:'application/json'}});if(!response.ok)throw new Error('Não foi possível acompanhar a operação.');operation.value=(await response.json()).data;if(['pending','applying','partial'].includes(operation.value?.state??''))setTimeout(()=>watchOperation(operationId).catch(error=>{toast.value=error instanceof Error?error.message:'Falha ao acompanhar operação.'}),1500);else await store.load()}
async function applySimulation(){if(!simulation.value||!pendingIntent.value)return;try{const intent={...pendingIntent.value};const response=await fetch('/api/v1/schedule/apply',{method:'POST',headers:{'Content-Type':'application/json',Accept:'application/json',...csrfHeaders()},body:JSON.stringify({commandId:simulation.value.command_id,intent})});if(!response.ok)throw new Error('Não foi possível registrar a operação.');const data=(await response.json()).data;simulation.value=null;pendingIntent.value=null;operationIntent.value=intent;operation.value={operation_id:data.operation_id,state:data.state,items:[]};await watchOperation(data.operation_id);toast.value='Operação enviada para aplicação'}catch(error){toast.value=error instanceof Error?error.message:'Não foi possível registrar a operação.'}setTimeout(()=>toast.value='',4500)}
async function recalculateConflict(){if(!operationIntent.value)return;const source=store.workspace?.tasks.find(item=>item.id===operationIntent.value?.taskId);if(!source)return;await simulate({...source,start:operationIntent.value.start,finish:operationIntent.value.finish})}
async function recoverSync(){if(syncState.value==='reauthorization_required'){needsTodoist.value=true;eventSource?.close();return}try{await store.load();await loadSyncStatus();syncState.value=store.workspace?.project.sync_status??'synced';toast.value='Sincronização atualizada'}catch(error){toast.value=error instanceof Error?error.message:'Não foi possível atualizar a sincronização.'}setTimeout(()=>toast.value='',3500)}
async function responseError(response:Response,fallback:string){try{const payload=await response.json();return typeof payload?.message==='string'?payload.message:fallback}catch{return fallback}}
async function createDependency(from:string,to:string,type:'FS'|'SS'|'FF'|'SF'){const response=await fetch('/api/v1/dependencies',{method:'POST',headers:{'Content-Type':'application/json',Accept:'application/json',...csrfHeaders()},body:JSON.stringify({from,to,type,commandId:crypto.randomUUID()})});if(!response.ok)throw new Error(await responseError(response,'Não foi possível criar a dependência.'));return (await response.json()).data as Dependency}
async function addDependency(){if(!activeTask.value||!dependencyTarget.value)return;try{await createDependency(activeTask.value.id,dependencyTarget.value,dependencyType.value);await store.load();dependencyTarget.value='';toast.value='Dependência adicionada'}catch(error){toast.value=error instanceof Error?error.message:'Não foi possível criar a dependência.'}setTimeout(()=>toast.value='',4000)}
async function removeDependency(id:string){try{const response=await fetch(`/api/v1/dependencies/${id}`,{method:'DELETE',headers:{'Content-Type':'application/json',Accept:'application/json',...csrfHeaders()},body:JSON.stringify({commandId:crypto.randomUUID()})});if(!response.ok)throw new Error('Não foi possível remover a dependência.');await store.load();toast.value='Dependência removida'}catch(error){toast.value=error instanceof Error?error.message:'Não foi possível remover a dependência.'}setTimeout(()=>toast.value='',4000)}
function requestAddDependency(){if(!activeTask.value||!dependencyTarget.value)return;dependencyConfirmation.value={action:'add',from:activeTask.value.id,to:dependencyTarget.value,type:dependencyType.value}}
function requestRemoveDependency(id:string){dependencyConfirmation.value={action:'remove',id}}
async function confirmDependency(){const confirmation=dependencyConfirmation.value;dependencyConfirmation.value=null;if(!confirmation)return;if(confirmation.action==='add')await addDependency();else if(confirmation.id)await removeDependency(confirmation.id)}
function installGestureListeners(){window.addEventListener('pointermove',gesturePointerMove,{passive:false});window.addEventListener('pointerup',gesturePointerUp);window.addEventListener('pointercancel',cancelTimeblockGesture);window.addEventListener('keydown',gestureKeydown,true)}
function removeGestureListeners(){window.removeEventListener('pointermove',gesturePointerMove);window.removeEventListener('pointerup',gesturePointerUp);window.removeEventListener('pointercancel',cancelTimeblockGesture);window.removeEventListener('keydown',gestureKeydown,true)}
function cancelTimeblockGesture(){if(timeGesture.value?.committing)return;removeGestureListeners();cancelGestureState()}
function autoScrollGesture(event:PointerEvent,allowVertical=false){const timeline=timelineElement.value;if(!timeline)return;const rect=timeline.getBoundingClientRect(),edge=38,speed=18;if(event.clientX<rect.left+taskPaneWidth.value+edge)timeline.scrollLeft=Math.max(0,timeline.scrollLeft-speed);else if(event.clientX>rect.right-edge)timeline.scrollLeft+=speed;if(!allowVertical)return;if(event.clientY<rect.top+edge)timeline.scrollTop=Math.max(0,timeline.scrollTop-speed);else if(event.clientY>rect.bottom-edge)timeline.scrollTop+=speed}
function updateConnectionPointer(gesture:ConnectGesture,event:PointerEvent){const rect=timelinePlane.value?.getBoundingClientRect();if(rect){gesture.pointerX=event.clientX-rect.left;gesture.pointerY=event.clientY-rect.top}const port=(document.elementFromPoint(event.clientX,event.clientY) as HTMLElement|null)?.closest<HTMLElement>('.dependency-port');gesture.targetTaskId=port?.dataset.taskId??null;gesture.targetEndpoint=(port?.dataset.endpoint as TimeEndpoint|undefined)??null}
function gesturePointerMove(event:PointerEvent){const gesture=timeGesture.value;if(!gesture||gesture.committing)return;event.preventDefault();autoScrollGesture(event,gesture.kind==='connect');if(gesture.kind==='move'){const delta=Math.round((event.clientX-gesture.originX)/dayWidth.value);gesture.moved=gesture.moved||Math.abs(event.clientX-gesture.originX)>=3;gesture.previewStart=shiftCivilDate(gesture.start,delta);gesture.previewFinish=shiftCivilDate(gesture.finish,delta)}else if(gesture.kind==='resize'){const preview=resizePreview({edge:gesture.edge,originX:gesture.originX,pointerX:event.clientX,dayWidth:dayWidth.value,start:gesture.start,finish:gesture.finish,earliestStart:gesture.earliestStart});gesture.moved=gesture.moved||Math.abs(event.clientX-gesture.originX)>=3;gesture.previewStart=preview.start;gesture.previewFinish=preview.finish;gesture.limited=preview.limited}else updateConnectionPointer(gesture,event)}
function gesturePointerUp(){const gesture=timeGesture.value;if(!gesture)return;if(gesture.kind==='connect')void commitConnectionGesture();else void commitDateGesture()}
function gestureKeydown(event:KeyboardEvent){const gesture=timeGesture.value;if(!gesture)return;if(event.key==='Escape'){event.preventDefault();event.stopPropagation();cancelTimeblockGesture();return}if(gesture.kind==='resize'&&(event.key==='ArrowLeft'||event.key==='ArrowRight')){event.preventDefault();event.stopPropagation();const delta=event.key==='ArrowLeft'?-1:1;if(gesture.edge==='finish'){const candidate=shiftCivilDate(gesture.previewFinish,delta);gesture.previewFinish=candidate<gesture.previewStart?gesture.previewStart:candidate;gesture.limited=candidate<gesture.previewStart}else{const candidate=shiftCivilDate(gesture.previewStart,delta),minimum=gesture.earliestStart;gesture.previewStart=minimum&&candidate<minimum?minimum:candidate>gesture.previewFinish?gesture.previewFinish:candidate;gesture.limited=gesture.previewStart!==candidate}gesture.moved=true}else if(gesture.kind==='resize'&&(event.key==='Enter'||event.key===' ')){event.preventDefault();event.stopPropagation();void commitDateGesture()}}
function startDrag(task:Task,event:PointerEvent){if(!canDragTask(task))return;event.preventDefault();const start=visualStart(task),finish=visualFinish(task);if(beginTimeGesture({kind:'move',taskId:task.id,originX:event.clientX,start,finish,previewStart:start,previewFinish:finish,moved:false,committing:false}))installGestureListeners()}
function startResize(task:Task,edge:TimeEndpoint,event?:PointerEvent){if(!canResizeTask(task))return;event?.preventDefault();event?.stopPropagation();const start=visualStart(task),finish=visualFinish(task);if(beginTimeGesture({kind:'resize',edge,taskId:task.id,originX:event?.clientX??0,start,finish,earliestStart:task.earliest_start??null,previewStart:start,previewFinish:finish,moved:false,limited:false,committing:false}))installGestureListeners()}
function resizeGripKeydown(task:Task,edge:TimeEndpoint,event:KeyboardEvent){if(!['Enter',' '].includes(event.key))return;event.preventDefault();event.stopPropagation();if(timeGesture.value?.kind==='resize')void commitDateGesture();else startResize(task,edge)}
async function commitDateGesture(){const gesture=timeGesture.value;if(!gesture||gesture.kind==='connect'||gesture.committing)return;removeGestureListeners();if(!gesture.moved){finishGestureState();return}gesture.committing=true;const intent=gesture.kind==='move'?'MOVE':gesture.edge==='start'?'RESIZE_START':'RESIZE_END';const body:Record<string,string>={intent,commandId:crypto.randomUUID()};if(intent==='MOVE'||intent==='RESIZE_START')body.start=gesture.previewStart;if(intent==='RESIZE_START'||intent==='RESIZE_END')body.deadline=gesture.previewFinish;try{const response=await fetch(`/api/v1/tasks/${gesture.taskId}/dates`,{method:'PUT',headers:{'Content-Type':'application/json',Accept:'application/json',...csrfHeaders()},body:JSON.stringify(body)});if(!response.ok)throw new Error(await responseError(response,'Não foi possível atualizar as datas da tarefa no Todoist.'));await store.load();toast.value=intent==='MOVE'?'Data atualizada no Todoist':'Duração atualizada e planejamento recalculado'}catch(error){toast.value=error instanceof Error?error.message:'Não foi possível atualizar as datas da tarefa.'}finally{finishGestureState();setTimeout(()=>toast.value='',4000)}}
function endpointPoint(task:Task,endpoint:TimeEndpoint){return{x:endpoint==='start'?px(visualStart(task)):px(visualFinish(task))+dayWidth.value,y:rowOffset(task.id)+rowHeight.value/2}}
function wouldCreateClientCycle(from:string,to:string){const outgoing=new Map<string,string[]>();for(const dependency of store.workspace?.dependencies??[]){const targets=outgoing.get(dependency.from)??[];targets.push(dependency.to);outgoing.set(dependency.from,targets)}const pending=[to],seen=new Set<string>();while(pending.length){const current=pending.pop()!;if(current===from)return true;if(seen.has(current))continue;seen.add(current);pending.push(...(outgoing.get(current)??[]))}return false}
function connectionValidation(task:Task,endpoint:TimeEndpoint){const gesture=timeGesture.value;if(!gesture||gesture.kind!=='connect')return{valid:true,reason:'',type:null as 'FS'|'SS'|'FF'|'SF'|null};const type=dependencyTypeFor(gesture.endpoint,endpoint);if(task.id===gesture.taskId)return{valid:false,reason:'Uma tarefa não pode depender dela mesma.',type};if(!canConnectTo(task))return{valid:false,reason:'Grupos podem ser somente predecessores.',type};if((store.workspace?.dependencies??[]).some(item=>item.from===gesture.taskId&&item.to===task.id&&item.type===type))return{valid:false,reason:'Essa dependência já existe.',type};if(wouldCreateClientCycle(gesture.taskId,task.id))return{valid:false,reason:'Essa dependência criaria um ciclo.',type};return{valid:true,reason:'',type}}
function startConnection(task:Task,endpoint:TimeEndpoint,event?:PointerEvent){if(!canConnectFrom(task))return;event?.preventDefault();event?.stopPropagation();const point=endpointPoint(task,endpoint);if(beginTimeGesture({kind:'connect',taskId:task.id,endpoint,pointerX:point.x,pointerY:point.y,targetTaskId:null,targetEndpoint:null,committing:false}))installGestureListeners()}
function dependencyPortKeydown(task:Task,endpoint:TimeEndpoint,event:KeyboardEvent){if(!['Enter',' '].includes(event.key))return;event.preventDefault();event.stopPropagation();const gesture=timeGesture.value;if(!gesture)startConnection(task,endpoint);else if(gesture.kind==='connect'){gesture.targetTaskId=task.id;gesture.targetEndpoint=endpoint;void commitConnectionGesture()}}
const connectionPreview=computed(()=>{const gesture=timeGesture.value;if(!gesture||gesture.kind!=='connect')return null;const source=visibleTasks.value.find(task=>task.id===gesture.taskId);if(!source)return null;const from=endpointPoint(source,gesture.endpoint),target=gesture.targetTaskId?visibleTasks.value.find(task=>task.id===gesture.targetTaskId):null,to=target&&gesture.targetEndpoint?endpointPoint(target,gesture.targetEndpoint):{x:gesture.pointerX,y:gesture.pointerY};const type=target&&gesture.targetEndpoint?dependencyTypeFor(gesture.endpoint,gesture.targetEndpoint):null,mid=from.x+(to.x-from.x)/2;return{path:`M${from.x},${from.y} C${mid},${from.y} ${mid},${to.y} ${to.x},${to.y}`,x:mid,y:(from.y+to.y)/2,type}})
async function commitConnectionGesture(){const gesture=timeGesture.value;if(!gesture||gesture.kind!=='connect'||gesture.committing)return;removeGestureListeners();const target=gesture.targetTaskId?visibleTasks.value.find(task=>task.id===gesture.targetTaskId):null;if(!target||!gesture.targetEndpoint){finishGestureState();return}const validation=connectionValidation(target,gesture.targetEndpoint);if(!validation.valid||!validation.type){toast.value=validation.reason||'Destino inválido para a dependência.';finishGestureState();setTimeout(()=>toast.value='',4000);return}gesture.committing=true;try{const dependency=await createDependency(gesture.taskId,target.id,validation.type);await store.load();undoDependencyId.value=dependency.id;toast.value=`Dependência ${validation.type} criada. Desfazer?`}catch(error){toast.value=error instanceof Error?error.message:'Não foi possível criar a dependência.'}finally{finishGestureState();setTimeout(()=>{toast.value='';undoDependencyId.value=null},6000)}}
async function undoLastDependency(){const id=undoDependencyId.value;if(!id)return;undoDependencyId.value=null;await removeDependency(id)}
function gesturePreviewFor(task:Task){const gesture=timeGesture.value;return gesture&&gesture.kind!=='connect'&&gesture.taskId===task.id?gesture:null}
async function persistTask(task:Task){const csrf=document.querySelector<HTMLMetaElement>('meta[name="csrf-token"]')?.content;const response=await fetch(`/api/v1/tasks/${task.id}`,{method:'PUT',headers:{'Content-Type':'application/json',Accept:'application/json',...(csrf?{'X-CSRF-TOKEN':csrf}:{})},body:JSON.stringify({title:task.title,priority:task.priority??1,completed:task.completed??task.status==='completed',commandId:crypto.randomUUID()})});if(!response.ok)throw new Error('Não foi possível salvar a tarefa no Todoist.');store.updateTask(task)}
async function persistCompletionDate(task:Task){if(!(task.completed??task.status==='completed')||!task.effective_completion)return;const response=await fetch(`/api/v1/tasks/${task.id}/completion-date`,{method:'PUT',headers:{'Content-Type':'application/json',Accept:'application/json',...csrfHeaders()},body:JSON.stringify({completionDate:task.effective_completion,commandId:crypto.randomUUID()})});if(!response.ok)throw new Error('Não foi possível salvar a data efetiva de conclusão.')}
async function createTask(){if(!newTaskTitle.value.trim())return;creating.value=true;try{const response=await fetch('/api/v1/tasks',{method:'POST',headers:{'Content-Type':'application/json',Accept:'application/json',...csrfHeaders()},body:JSON.stringify({title:newTaskTitle.value.trim(),commandId:crypto.randomUUID()})});if(!response.ok)throw new Error('Não foi possível criar a tarefa.');newTaskTitle.value='';creating.value=false;await store.load();toast.value='Tarefa criada no Todoist'}catch(error){creating.value=false;toast.value=error instanceof Error?error.message:'Não foi possível criar a tarefa.'}setTimeout(()=>toast.value='',3500)}
async function previewDeletion(){if(!activeTask.value||activeTask.value.kind!=='task')return;try{const response=await fetch(`/api/v1/tasks/${activeTask.value.id}/deletion-preview`,{method:'POST',headers:{Accept:'application/json',...csrfHeaders()}});if(!response.ok)throw new Error('Não foi possível calcular o impacto da exclusão.');deletionPreview.value=(await response.json()).data}catch(error){toast.value=error instanceof Error?error.message:'Não foi possível calcular o impacto.';setTimeout(()=>toast.value='',3500)}}
async function deleteTask(){if(!activeTask.value||!deletionPreview.value)return;deleting.value=true;try{const response=await fetch(`/api/v1/tasks/${activeTask.value.id}`,{method:'DELETE',headers:{'Content-Type':'application/json',Accept:'application/json',...csrfHeaders()},body:JSON.stringify({confirmed:true,preserveContinuity:preserveContinuity.value,commandId:crypto.randomUUID()})});if(!response.ok)throw new Error('Não foi possível excluir a tarefa.');finishTaskEditorClose();await store.load();toast.value='Tarefa excluída'}catch(error){toast.value=error instanceof Error?error.message:'Não foi possível excluir a tarefa.'}finally{deleting.value=false;setTimeout(()=>toast.value='',3500)}}
async function saveTask(){if(!activeTask.value)return;const task={...activeTask.value},source=store.workspace?.tasks.find(item=>item.id===task.id),pending=pendingTaskToOpen.value;try{const datesChanged=Boolean(source&&(task.start!==source.start||task.finish!==source.finish));if(datesChanged&&!await simulate(task))return;const nativeChanged=!source||task.title!==source.title||(task.priority??1)!==(source.priority??1)||(task.completed??task.status==='completed')!==(source.completed??source.status==='completed')||task.effective_completion!==source.effective_completion;if(nativeChanged){const nativeTask=source?{...task,start:source.start,finish:source.finish}:task;await persistTask(nativeTask);await persistCompletionDate(task)}toast.value=datesChanged?'Cenário calculado. Revise e aplique a operação para confirmar as datas.':'Alterações salvas no Todoist';finishTaskEditorClose(!pending);if(pending)openTaskImmediately(pending);setTimeout(()=>toast.value='',4500)}catch(error){toast.value=error instanceof Error?error.message:'Não foi possível salvar as alterações';setTimeout(()=>toast.value='',4500)}}
function statusLabel(s:string){return ({completed:'Concluída',blocked:'Bloqueada',scheduled:'Agendada',late:'Atrasada',opened:'Aberta'} as Record<string,string>)[s]}
</script>

<template>
<main v-if="auth.loading" class="loading"><div class="loader-logo">G</div><p>Verificando seu acesso…</p></main>
<AuthGate v-else-if="!auth.user" :auth="auth" />
<TodoistSetup v-else-if="needsTodoist" @ready="needsTodoist=false;store.load()" />
<div v-else class="app-shell" :class="[`text-${textScale}`, `space-${spacing}`,{'editor-pinned':drawer&&activeTask&&editorPinned}]" :style="{'--task-editor-width':editorWidth+'px'}">
  <header class="topbar">
    <div class="brand"><span class="brand-mark"><i></i><i></i><i></i></span><strong>Ganttist</strong></div>
    <div class="project-switcher"><span class="eyebrow">PROJETO TODOIST</span><button :aria-expanded="projectMenu" aria-haspopup="listbox" @click="toggleProjectMenu"><span class="project-dot"></span>{{store.workspace?.project.name||'Carregando…'}} <span class="chevron">⌄</span></button><div v-if="projectMenu" class="project-menu" role="listbox" aria-label="Projetos Todoist"><span v-if="projectLoading">Carregando projetos…</span><button v-for="project in projects" :key="project.id" role="option" :aria-selected="project.id===store.workspace?.project.id" @click="switchProject(project)">{{project.name}}</button></div></div>
    <div class="top-actions">
      <div class="appearance-wrap"><button class="icon-btn appearance-btn" aria-label="Aparência" title="Aparência" @click="appearance=!appearance">A<span>a</span></button><div v-if="appearance" class="appearance-menu"><b>Aparência</b><label>Tamanho do texto<select v-model="textScale"><option value="compact">Menor</option><option value="comfortable">Confortável</option><option value="large">Maior</option></select></label><label>Espaçamento<select v-model="spacing"><option value="compact">Compacto</option><option value="comfortable">Confortável</option><option value="spacious">Espaçoso</option></select></label></div></div>
      <button class="sync-pill" :class="syncState" :aria-label="`${syncLabel}. Abrir diagnóstico de sincronização.`" @click="syncDiagnostics=!syncDiagnostics"><span class="pulse"></span><span><b>{{syncLabel}}</b><small>{{syncState==='synced'?'dados reconciliados':syncState==='reauthorization_required'?'conectar novamente':'tentar atualizar'}}</small></span></button><section v-if="syncDiagnostics" class="sync-diagnostics" role="dialog" aria-label="Diagnóstico de sincronização"><b>{{syncLabel}}</b><span>Última reconciliação: {{syncInfo.lastSyncedAt?new Date(syncInfo.lastSyncedAt).toLocaleString('pt-BR'):'ainda não realizada'}}</span><span>Pendências: {{syncInfo.pending}} · Conflitos: {{syncInfo.conflicts}}</span><small v-if="syncInfo.error">{{syncInfo.error}}</small><button class="soft-btn" :disabled="store.refreshing" @click="recoverSync">{{syncState==='reauthorization_required'?'Reconectar':'Reconciliar agora'}}</button></section>
      <button class="icon-btn" aria-label="Notificações" @click="notices=!notices">◴<em>3</em></button>
      <button class="icon-btn" aria-label="Abrir histórico do projeto" title="Histórico" @click="historyPanel=true">≡</button>
      <button class="icon-btn" aria-label="Configurar calendário do projeto" title="Calendário" @click="calendarPanel=true">▣</button>
      <button class="avatar" aria-label="Abrir sessões e configurações da conta" :aria-expanded="account" aria-haspopup="dialog" @click="account=true">{{(auth.user.name||auth.user.email).slice(0,2).toUpperCase()}}</button>
    </div>
  </header>

  <main v-if="store.loading" class="loading"><div class="loader-logo">G</div><p>Organizando seu planejamento…</p></main>
  <main v-else-if="store.error" class="loading"><p>{{store.error}}</p><button class="primary" @click="store.load">Tentar novamente</button></main>
  <main v-else-if="store.empty" class="loading"><div><p>Este projeto ainda não possui tarefas.</p><button class="primary" :disabled="store.refreshing" @click="store.load">Atualizar projeto</button></div></main>
  <main v-else class="main">
    <section class="commandbar">
      <div class="title-block"><div><span class="eyebrow">VISÃO DE PLANEJAMENTO</span><h1>{{store.workspace?.project.name}}</h1></div><span v-if="store.workspace?.project.id==='demo-product-launch'" class="demo-badge">AMBIENTE DEMO</span></div>
      <div class="commands">
        <label class="search"><span>⌕</span><input v-model="store.search" placeholder="Buscar tarefa…"><kbd>⌘ K</kbd></label>
        <div class="segmented"><button :class="{active:store.zoom==='day'}" @click="store.zoom='day'">Dia</button><button :class="{active:store.zoom==='week'}" @click="store.zoom='week'">Semana</button><button :class="{active:store.zoom==='month'}" @click="store.zoom='month'">Mês</button></div>
        <button class="soft-btn" @click="filters=!filters">≡ Filtros <span v-if="store.statusFilter!=='all'" class="count">1</span></button>
        <button class="soft-btn" @click="creating=!creating">＋ Tarefa</button><button class="primary" @click="simulate()"><span v-if="simulating" class="spinner"></span><span v-else>✦</span> {{simulating?'Calculando…':'Simular cenário'}}</button><button v-if="simulation?.changes.length" class="soft-btn" @click="applySimulation">Aplicar {{simulation.changes.length}} alterações</button>
      </div>
    </section>

    <div v-if="creating" class="create-task" role="region" aria-label="Criar tarefa"><input v-model="newTaskTitle" placeholder="Nome da nova tarefa" @keyup.enter="createTask"><button class="soft-btn" @click="creating=false">Cancelar</button><button class="primary" :disabled="creating&& !newTaskTitle.trim()" @click="createTask">Criar no Todoist</button></div>
    <div v-if="operation" class="operation-status" :class="operation.state"><b>Operação {{operation.state}}</b><span>{{operation.items.filter(item=>item.state==='applied').length}}/{{operation.items.length}} itens aplicados</span><small v-if="operation.error">{{operation.error}}</small><button v-if="operation.state==='conflict'&&operationIntent" class="soft-btn" @click="recalculateConflict">Recalcular com dados atuais</button></div>
    <section v-if="simulation" class="simulation-review" role="region" aria-label="Revisão da simulação"><div><b>Revise {{simulation.changes.length}} alteração(ões) calculada(s)</b><small>Os ghosts são apenas uma prévia. Nada será salvo antes de confirmar.</small></div><ul><li v-for="change in simulation.changes" :key="change.task_id">{{taskTitle(change.task_id)}}: {{change.start}} → {{change.finish}}</li></ul><div><button class="soft-btn" @click="simulation=null;pendingIntent=null">Descartar</button><button class="primary" @click="applySimulation">Confirmar operação</button></div></section>
    <div v-if="store.stale" class="workspace-state" role="status"><span>Exibindo o último estado conhecido; a atualização remota falhou.</span><button class="soft-btn" :disabled="store.refreshing" @click="store.load">{{store.refreshing?'Atualizando…':'Tentar novamente'}}</button></div>
    <section class="stats-row">
      <article><span class="stat-icon violet">◔</span><div><small>PROGRESSO GERAL</small><b>{{store.workspace?.stats.progress}}%</b></div><div class="mini-progress"><i :style="{width:store.workspace?.stats.progress+'%'}"></i></div></article>
      <article><span class="stat-icon green">✓</span><div><small>CONCLUÍDAS</small><b>{{store.workspace?.stats.completed}} <em>/ {{store.workspace?.stats.total}}</em></b></div><span class="trend">+2 esta semana</span></article>
      <article><span class="stat-icon coral">⌁</span><div><small>CAMINHO CRÍTICO</small><b>{{store.workspace?.stats.critical}} <em>tarefas</em></b></div><span class="risk">ATENÇÃO</span></article>
      <article><span class="stat-icon amber">⊘</span><div><small>BLOQUEADAS</small><b>{{store.workspace?.stats.blocked??0}} <em>tarefas</em></b></div><button @click="store.statusFilter='blocked'">Revisar →</button></article>
    </section>

    <div v-if="filters" class="filter-popover" role="group" aria-label="Filtrar por estado calculado"><b>Filtrar por estado calculado</b><button type="button" :class="{active:store.statusFilter==='all'}" :aria-pressed="store.statusFilter==='all'" @click="store.statusFilter='all'">Todas</button><section class="filter-status-group" role="group" aria-labelledby="unblocked-filter-label"><button id="unblocked-filter-label" type="button" class="filter-status-parent" :class="{active:store.statusFilter==='unblocked','contains-active':['opened','scheduled','late'].includes(store.statusFilter)}" :aria-pressed="store.statusFilter==='unblocked'" @click="store.statusFilter='unblocked'"><span aria-hidden="true">⌄</span>Desbloqueadas</button><div class="filter-status-children"><button v-for="f in [['opened','Abertas'],['scheduled','Agendadas'],['late','Atrasadas']] as const" :key="f[0]" type="button" :class="{active:store.statusFilter===f[0]}" :aria-pressed="store.statusFilter===f[0]" @click="store.statusFilter=f[0]">{{f[1]}}</button></div></section><button type="button" :class="{active:store.statusFilter==='blocked'}" :aria-pressed="store.statusFilter==='blocked'" @click="store.statusFilter='blocked'">Bloqueadas</button><button type="button" :class="{active:store.statusFilter==='completed'}" :aria-pressed="store.statusFilter==='completed'" @click="store.statusFilter='completed'">Concluídas</button></div>

    <section ref="ganttCard" class="gantt-card" :class="{'has-selection':store.selected.length>0}">
      <div ref="ganttHeadLeft" class="gantt-head-left"><span>TAREFA</span><span>RESP.</span><span>STATUS</span></div>
      <div class="timeline-head">
        <div class="months" :style="{width:days.length*dayWidth+'px',transform:`translateX(${-scrollLeft}px)`}"><span v-for="m in monthSegments" :style="{width:m.span*dayWidth+'px'}">{{m.label}}</span></div>
        <div class="day-heads"><span v-for="day in renderedDays" :class="{weekend:[0,6].includes(day.date.getDay()),today:day.date.toISOString().slice(0,10)===todayCivil()}" :style="{width:dayWidth+'px',left:(day.index*dayWidth-scrollLeft)+'px'}"><b>{{day.date.toLocaleDateString('pt-BR',{weekday:'short'}).slice(0,3)}}</b>{{day.date.getDate()}}</span></div>
      </div>
      <div ref="timelineElement" class="gantt-scroll" role="tree" aria-label="Linhas e cronograma do projeto" tabindex="0" @focus="adoptTimelineCursor" @keydown="ganttKeydown" @scroll="onTimelineScroll">
        <div class="gantt-body" role="none" :style="{width:taskPaneWidth+days.length*dayWidth+'px',height:visibleTasks.length*rowHeight+'px'}">
          <div class="task-pane-surface" aria-hidden="true" :style="{width:taskPaneWidth+'px',height:visibleTasks.length*rowHeight+'px'}"></div>
          <div ref="timelinePlane" class="timeline-plane" role="none" :style="{left:taskPaneWidth+'px',width:days.length*dayWidth+'px',height:visibleTasks.length*rowHeight+'px'}">
            <div v-for="day in renderedDays" :key="day.date.toISOString()" class="day-column" :class="{weekend:[0,6].includes(day.date.getDay())}" :style="{left:day.index*dayWidth+'px',width:dayWidth+'px'}"></div>
            <div class="today-line" :style="{left:px(todayCivil())+'px'}"><span>HOJE</span></div>
            <svg class="dependencies" :width="days.length*dayWidth" :height="visibleTasks.length*rowHeight"><defs><marker id="arrow" markerWidth="6" markerHeight="6" refX="5" refY="3" orient="auto"><path d="M0 0 L6 3 L0 6Z"/></marker><marker id="arrow-critical" markerWidth="6" markerHeight="6" refX="5" refY="3" orient="auto"><path d="M0 0 L6 3 L0 6Z"/></marker></defs><path v-for="dep in store.workspace?.dependencies" :key="dep.id" :d="pathFor(dep)" :class="{critical:dep.critical}" marker-end="url(#arrow)"/></svg>
            <svg v-if="connectionPreview" class="connection-preview" :width="days.length*dayWidth" :height="visibleTasks.length*rowHeight" aria-hidden="true"><path :d="connectionPreview.path"/></svg>
            <span v-if="connectionPreview?.type" class="connection-type-badge" :style="{left:connectionPreview.x+'px',top:connectionPreview.y+'px'}">{{connectionPreview.type}}</span>
            <div v-for="ghost in ghostChanges" :key="ghost.change.task_id" class="task-ghost" :style="{left:px(ghost.change.start)+'px',top:ghost.index*rowHeight+14+'px',width:barWidth(ghost.change.start,ghost.change.finish,dayWidth)+'px'}"><span>Prévia</span></div>
          </div>
          <div v-for="(task,renderedIndex) in renderedTasks" :key="task.id" class="gantt-row" role="none" :style="{top:rowOffset(task.id)+'px',height:rowHeight+'px',width:taskPaneWidth+days.length*dayWidth+'px'}" @mouseenter="hoveredTaskId=task.id" @mouseleave="hoveredTaskId=null" @dblclick="openTaskFromDoubleClick(task,$event)">
            <div class="task-row" role="treeitem" :data-task-id="task.id" :aria-level="task.level+1" :aria-expanded="isExpandable(task)?!store.hiddenGroups.has(task.id):undefined" :aria-selected="task.kind==='task'?store.selected.includes(task.id):undefined" :tabindex="cursorTaskId===task.id||(!cursorTaskId&&virtualStart+renderedIndex===0)?0:-1" :class="[{section:task.kind==='section',parent:isExpandable(task),selected:store.selected.includes(task.id),hovered:hoveredTaskId===task.id,'hierarchy-ancestor':isHoveredAncestor(task),cursor:cursorTaskId===task.id,'calendar-inconsistent':task.calendar_inconsistent},task.status]" :style="{height:rowHeight+'px',width:taskPaneWidth+'px'}" @focus="cursorTaskId=task.id" @click="moveCursorTo(task)" @keydown="rowKeydown(task,$event)">
              <div class="task-name" :style="{'--tree-row-height':rowHeight+'px'}"><span class="task-selection-slot"><input v-if="task.kind==='task'" class="task-check" type="checkbox" :checked="store.selected.includes(task.id)" :aria-label="`Selecionar ${task.title}`" @click.stop="selectFromCheckbox(task,$event)"></span><div class="task-tree-content" :class="{'has-expanded-children':isExpandable(task)&&!store.hiddenGroups.has(task.id),'node-down-active':isTreeSegmentActive(task,task.level,'down')}" :style="{'--tree-depth':task.level}"><span v-if="task.level" class="tree-prefix" aria-hidden="true"><svg v-for="(ancestorId,depth) in ancestorsFor(task)" :key="ancestorId" class="tree-slot" :class="{'current-branch':isCurrentBranch(task,depth),'ancestor-slot':!isCurrentBranch(task,depth)}" width="22" :height="rowHeight" viewBox="0 0 22 100" preserveAspectRatio="none"><path v-if="isCurrentBranch(task,depth)" class="tree-segment-base tree-branch-path" d="M11 0 V44 Q11 50 17 50 H22"></path><path v-if="isCurrentBranch(task,depth)&&hasNextSibling(task)" class="tree-segment-base tree-sibling-continuation" d="M11 44 V100"></path><path v-if="!isCurrentBranch(task,depth)&&ancestorSlotContinues(task,depth)" class="tree-segment-base tree-sibling-continuation" d="M11 0 V100"></path><path v-if="isCurrentBranch(task,depth)&&activeBranchPath(task,depth)" class="tree-segment-active" :d="activeBranchPath(task,depth)"></path><path v-if="activeVerticalPath(task,depth,isCurrentBranch(task,depth))" class="tree-segment-active" :d="activeVerticalPath(task,depth,isCurrentBranch(task,depth))"></path></svg></span><button v-if="isExpandable(task)" type="button" class="gantt-tree-toggle" :title="`${store.hiddenGroups.has(task.id)?'Expandir':'Recolher'} subitens`" :aria-label="`${store.hiddenGroups.has(task.id)?'Expandir':'Recolher'} ${task.title}`" :aria-expanded="!store.hiddenGroups.has(task.id)" @pointerdown.stop @click.stop.prevent="toggleExpansion(task)"><span class="gantt-tree-toggle-chevron" :class="{expanded:!store.hiddenGroups.has(task.id)}" aria-hidden="true">›</span></button><span v-else class="task-terminal-slot" :class="{'has-priority':taskPriorityLevel(task)}"><svg class="gantt-tree-toggle-spacer" :class="{connected:task.level>0,active:task.level>0&&isTreeSegmentActive(task,task.level-1,'right')}" width="22" :height="rowHeight" viewBox="0 0 22 100" preserveAspectRatio="none" aria-hidden="true"><path v-if="task.level>0" :d="taskPriorityLevel(task)?'M0 50 H6':'M0 50 H22'"></path></svg><svg v-if="taskPriorityLevel(task)" class="task-priority-flag" :class="`p${taskPriorityLevel(task)}`" viewBox="0 0 18 28" role="img" :aria-label="`Prioridade P${taskPriorityLevel(task)}`"><title>Prioridade P{{taskPriorityLevel(task)}}</title><path class="flag-pole" d="M4 2.5 V25.5"></path><path class="flag-cloth" d="M5 4 H16 L13 8.5 L16 13 H5 Z"></path></svg></span><div class="task-title"><div class="task-title-line"><b>{{task.title}}</b></div><small v-if="task.kind==='task'&&!isExpandable(task)&&task.description" class="task-description" :title="task.description">{{task.description}}</small></div></div></div>
              <div class="task-assignee"><template v-if="task.kind==='task'"><span v-if="task.assignee" class="mini-avatar">{{task.assignee}}</span><span v-else>—</span></template></div>
              <div class="task-status"><template v-if="task.kind==='task'"><span v-if="task.calendar_inconsistent" class="calendar-warning" title="A data cai em dia não útil; simule para corrigir">Calendário</span><span v-else class="status-label"><i></i>{{statusLabel(task.status)}}</span></template></div>
            </div>
            <div class="bar-lane" :class="{selected:store.selected.includes(task.id),hovered:hoveredTaskId===task.id,'hierarchy-ancestor':isHoveredAncestor(task),cursor:cursorTaskId===task.id}" :style="{left:taskPaneWidth+'px',height:rowHeight+'px'}" @click="moveCursorTo(task)">
              <div v-if="gesturePreviewFor(task)" class="task-bar drag-ghost" :class="[`gesture-${gesturePreviewFor(task)?.kind}`,{committing:gesturePreviewFor(task)?.committing,provisional:!task.start}]" :style="{left:px(gesturePreviewFor(task)!.previewStart)+'px',width:barWidth(gesturePreviewFor(task)!.previewStart,gesturePreviewFor(task)!.previewFinish,dayWidth)+'px'}" :aria-label="`${gesturePreviewFor(task)?.kind==='move'?'Movendo':'Redimensionando'} ${task.title}: ${gesturePreviewFor(task)?.previewStart} até ${gesturePreviewFor(task)?.previewFinish}`"></div>
              <div v-else class="task-bar" :class="[task.kind,task.status,{critical:task.critical,summary:isExpandable(task),parent:task.has_children,provisional:task.kind==='task'&&!civilDate(task.start),'calendar-inconsistent':task.calendar_inconsistent,'controls-visible':cursorTaskId===task.id||gestureMode==='connect'}]" :style="{left:px(visualStart(task))+'px',width:width(task)+'px'}" :aria-label="`${task.title}: ${civilDate(task.start)??'sem data, exibida provisoriamente em hoje'}`" :title="task.title" @click.stop="moveCursorTo(task)" @pointerdown.stop="moveCursorTo(task);startDrag(task,$event)">
                <template v-if="isExpandable(task)"><i class="group-line"></i><i class="group-left"></i><i class="group-right"></i></template>
                <template v-else><i class="progress-fill" :style="{width:task.progress+'%'}"></i></template>
                <template v-if="canResizeTask(task)"><button type="button" class="timeblock-grip start" title="Ajustar data inicial" :aria-label="`Ajustar início de ${task.title}`" @pointerdown.stop="startResize(task,'start',$event)" @keydown="resizeGripKeydown(task,'start',$event)"></button><button type="button" class="timeblock-grip finish" title="Ajustar deadline" :aria-label="`Ajustar deadline de ${task.title}`" @pointerdown.stop="startResize(task,'finish',$event)" @keydown="resizeGripKeydown(task,'finish',$event)"></button></template>
                <template v-if="canConnectFrom(task)"><button type="button" class="dependency-port start" :class="{visible:gestureMode==='connect','drop-target':timeGesture?.kind==='connect'&&timeGesture.targetTaskId===task.id&&timeGesture.targetEndpoint==='start',invalid:gestureMode==='connect'&&!connectionValidation(task,'start').valid}" :data-task-id="task.id" data-endpoint="start" :aria-label="`Conector de início de ${task.title}`" :aria-disabled="gestureMode==='connect'&&!connectionValidation(task,'start').valid" :title="gestureMode==='connect'?connectionValidation(task,'start').reason||'Conectar ao início':'Criar relação a partir do início'" @pointerdown.stop="startConnection(task,'start',$event)" @keydown="dependencyPortKeydown(task,'start',$event)"></button><button type="button" class="dependency-port finish" :class="{visible:gestureMode==='connect','drop-target':timeGesture?.kind==='connect'&&timeGesture.targetTaskId===task.id&&timeGesture.targetEndpoint==='finish',invalid:gestureMode==='connect'&&!connectionValidation(task,'finish').valid}" :data-task-id="task.id" data-endpoint="finish" :aria-label="`Conector de fim de ${task.title}`" :aria-disabled="gestureMode==='connect'&&!connectionValidation(task,'finish').valid" :title="gestureMode==='connect'?connectionValidation(task,'finish').reason||'Conectar ao fim':'Criar relação a partir do fim'" @pointerdown.stop="startConnection(task,'finish',$event)" @keydown="dependencyPortKeydown(task,'finish',$event)"></button></template>
              </div>
            </div>
          </div>
        </div>
      </div>
      <div v-if="store.selected.length" class="selection-bar" role="region" aria-label="Comandos da seleção"><b>{{store.selected.length}} tarefa(s) selecionada(s)</b><span aria-live="polite">Use os checkboxes; Shift seleciona um intervalo.</span><div><button class="soft-btn" :disabled="store.selected.length!==1" @click="openSelectedTask">Editar</button><button class="soft-btn" @click="simulate()">Simular</button><button class="soft-btn" @click="store.selected=[]">Limpar seleção</button></div></div>
      <div class="gantt-footer"><span><i class="legend opened"></i> Aberta</span><span><i class="legend blocked"></i> Bloqueada</span><span><i class="legend scheduled"></i> Agendada</span><span><i class="legend late"></i> Atrasada</span><span><i class="legend completed"></i> Concluída</span><span><i class="legend critical"></i> Caminho crítico</span><div class="footer-right">Fuso: América/São Paulo · Datas consideradas na projeção <button>?</button></div></div>
    </section>
  </main>

    <section v-if="hiddenDependencies.length" class="hidden-dependencies" aria-live="polite">
      <div><b>Relações ocultas pelos filtros ou recolhimento</b><p>Elas continuam ativas no planejamento e no cálculo do caminho crítico.</p></div>
      <ul><li v-for="dependency in hiddenDependencies" :key="dependency.id"><span :class="{critical:dependency.critical}">{{taskTitle(dependency.from)}} → {{taskTitle(dependency.to)}} ({{dependency.type}})</span><button @click="revealDependency(dependency)">Revelar</button></li></ul>
    </section>
  <aside class="drawer" :class="{open:drawer&&activeTask,pinned:editorPinned}" role="dialog" aria-modal="false" aria-labelledby="task-editor-title">
    <div v-if="editorPinned&&drawer" class="drawer-resizer" role="separator" aria-label="Redimensionar editor de tarefa" aria-orientation="vertical" :aria-valuemin="editorMinWidth" :aria-valuemax="editorMaxWidth()" :aria-valuenow="editorWidth" tabindex="0" @pointerdown="startEditorResize" @keydown="resizeEditorFromKeyboard"></div>
    <template v-if="activeTask">
      <header>
        <div><span class="eyebrow">DETALHES DA TAREFA</span><h2 id="task-editor-title">{{activeTask.title}}</h2></div>
        <div class="drawer-header-actions">
          <button class="drawer-pin" :class="{active:editorPinned}" :aria-pressed="editorPinned" :aria-label="editorPinned?'Soltar editor do layout':'Fixar editor no layout'" :title="editorPinned?'Soltar editor':'Fixar editor'" @click="toggleEditorPinned"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M8 3h8l-1 6 3 3v2h-5v7l-1 1-1-1v-7H6v-2l3-3-1-6Z"></path></svg></button>
          <button class="drawer-close" aria-label="Fechar editor" title="Fechar" @click="requestTaskEditorClose">×</button>
        </div>
      </header>
      <div class="drawer-body"><div class="source-line"><span class="todoist-mark">✓</span><div><b>Sincronizada com Todoist</b><small>Campos nativos são atualizados na origem; projeções permanecem somente no Gantt.</small></div></div><label>Título<input v-model="activeTask.title"></label><div class="form-grid"><label>Data inicial no Todoist<input v-model="activeTask.start" type="date"></label><label>Deadline no Todoist<input v-model="activeTask.finish" type="date"></label></div><label class="completion-toggle"><input v-model="activeTask.completed" type="checkbox"> Concluída no Todoist</label><section class="projection-summary" aria-label="Projeção calculada"><div><small>STATUS CALCULADO</small><b>{{statusLabel(activeTask.status)}}</b></div><div><small>INÍCIO CONSIDERADO</small><b>{{activeTask.considered_start||todayCivil()}}</b></div><div><small>DEADLINE CONSIDERADA</small><b>{{activeTask.considered_deadline||activeTask.considered_start||todayCivil()}}</b></div><div v-if="activeTask.unlock_date"><small>DATA DE DESBLOQUEIO</small><b>{{activeTask.unlock_date}}</b></div><p>Valores calculados para montar o Gantt; não são gravados automaticamente no Todoist.</p></section><label v-if="activeTask.completed">Data efetiva de conclusão <small>Override próprio usado no cálculo; não altera a conclusão no Todoist.</small><input v-model="activeTask.effective_completion" type="date"></label>
        <section class="dependency-box" aria-labelledby="task-relations-title">
          <header class="dependency-box-header"><span aria-hidden="true">⌁</span><div><b id="task-relations-title">Relações</b><small>{{predecessorDependencies.length}} predecessora(s) · {{dependentDependencies.length}} dependente(s)</small></div></header>
          <section class="dependency-direction" aria-labelledby="predecessor-relations-title"><header><b id="predecessor-relations-title">Depende de</b><span>{{predecessorDependencies.length}}</span></header><p v-if="!predecessorDependencies.length" class="dependency-empty">Nenhuma predecessora.</p><ul v-else><li v-for="dependency in predecessorDependencies" :key="dependency.id" class="dependency-item"><span class="dependency-type">[{{dependency.type}}]</span><span class="dependency-task-title" :title="taskTitle(dependency.from)">{{taskTitle(dependency.from)}}</span><button type="button" class="dependency-delete" :aria-label="`Remover dependência ${dependency.type} de ${taskTitle(dependency.from)}`" :title="`Remover relação com ${taskTitle(dependency.from)}`" @click="requestRemoveDependency(dependency.id)"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M9 3h6l1 2h4v2H4V5h4l1-2Zm-2 6h10l-.7 11H7.7L7 9Zm3 2v7h2v-7h-2Zm4 0v7h2v-7h-2Z"/></svg></button></li></ul></section>
          <section class="dependency-direction" aria-labelledby="dependent-relations-title"><header><b id="dependent-relations-title">Dependentes</b><span>{{dependentDependencies.length}}</span></header><p v-if="!dependentDependencies.length" class="dependency-empty">Nenhuma tarefa dependente.</p><ul v-else><li v-for="dependency in dependentDependencies" :key="dependency.id" class="dependency-item"><span class="dependency-type">[{{dependency.type}}]</span><span class="dependency-task-title" :title="taskTitle(dependency.to)">{{taskTitle(dependency.to)}}</span><button type="button" class="dependency-delete" :aria-label="`Remover dependente ${dependency.type} ${taskTitle(dependency.to)}`" :title="`Remover relação com ${taskTitle(dependency.to)}`" @click="requestRemoveDependency(dependency.id)"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M9 3h6l1 2h4v2H4V5h4l1-2Zm-2 6h10l-.7 11H7.7L7 9Zm3 2v7h2v-7h-2Zm4 0v7h2v-7h-2Z"/></svg></button></li></ul></section>
          <div class="dependency-form"><select v-model="dependencyTarget" aria-label="Tarefa dependente"><option value="">Outra tarefa…</option><option v-for="task in store.tasks.filter(t=>t.kind==='task'&&t.id!==activeTask?.id)" :key="task.id" :value="task.id">{{task.title}}</option></select><select v-model="dependencyType" aria-label="Tipo da dependência"><option value="FS">FS</option><option value="SS">SS</option><option value="FF">FF</option><option value="SF">SF</option></select><button @click="requestAddDependency">Adicionar</button></div><section v-if="dependencyConfirmation" class="dependency-confirm" role="alert"><b>{{dependencyConfirmation.action==='add'?'Confirmar nova dependência':'Remover dependência?'}}</b><p v-if="dependencyConfirmation.action==='add'">{{taskTitle(dependencyConfirmation.from!)}} → {{taskTitle(dependencyConfirmation.to!)}} ({{dependencyConfirmation.type}}). O core validará escopo e ciclo antes de persistir.</p><p v-else>A relação será removida do planejamento.</p><div><button class="soft-btn" @click="dependencyConfirmation=null">Cancelar</button><button class="primary" @click="confirmDependency">Confirmar</button></div></section>
        </section><section v-if="deletionPreview" class="delete-preview" role="alert"><b>Excluir esta tarefa?</b><p>{{deletionPreview.incoming.length}} entrada(s), {{deletionPreview.outgoing.length}} saída(s) e {{deletionPreview.continuity.length}} ligação(ões) de continuidade possíveis.</p><label><input v-model="preserveContinuity" type="checkbox"> Preservar continuidade (FS)</label><div><button class="soft-btn" @click="deletionPreview=null">Cancelar</button><button class="danger-btn" :disabled="deleting" @click="deleteTask">{{deleting?'Excluindo…':'Confirmar exclusão'}}</button></div></section></div>
      <section v-if="closeConfirmation" class="unsaved-confirm" role="alertdialog" aria-modal="true" aria-labelledby="unsaved-title" aria-describedby="unsaved-description"><b id="unsaved-title">Alterações não salvas</b><p id="unsaved-description">{{pendingTaskToOpen?'Salve ou descarte o rascunho antes de editar outra tarefa.':'Salve ou descarte o rascunho antes de fechar o editor.'}}</p><div><button class="soft-btn continue-editing" @click="continueTaskEditing">Continuar editando</button><button class="danger-btn discard-changes" @click="discardTaskDraft">Descartar alterações</button><button class="primary save-before-close" :disabled="simulating||deleting" @click="saveTask">Salvar alterações</button></div></section>
      <footer><button v-if="activeTask.kind==='task'&&!deletionPreview" class="danger-btn" @click="previewDeletion">Excluir</button><button class="soft-btn drawer-cancel" @click="requestTaskEditorClose">Cancelar</button><button class="primary" :disabled="simulating||deleting" @click="saveTask">{{simulating?'Salvando…':'Salvar alterações'}}</button></footer>
    </template>
  </aside>
  <div v-if="toast" class="toast" role="status"><span>✓</span>{{toast}}<button v-if="undoDependencyId" type="button" @click="undoLastDependency">Desfazer</button></div>
</div>
<AccountPanel :open="account" @close="account=false" @deleted="account=false;auth.logout()" />
<CalendarPanel :open="calendarPanel" @close="calendarPanel=false" @saved="calendarPanel=false;store.load()" />
<HistoryPanel :open="historyPanel" @close="historyPanel=false" />
</template>
